<script>
const acaApi='<?= BASE_URL ?>/controllers/admin/gestion-academica-api.php', acaSave='<?= BASE_URL ?>/controllers/admin/gestion-academica-save.php', acaCsrf=<?= json_encode($academicCsrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>, acaPage=<?= json_encode($academicTab) ?>;
let acaData={}; const acaStatus=document.getElementById('academicStatus');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labelMap={instrumentos:r=>`${r.abreviatura} — ${r.nombre_completo}`,periodos:r=>`${r.instrumento} · ${r.codigo} — ${r.nombre}`, 'periodos-filter':r=>`${r.instrumento} · ${r.codigo} — ${r.nombre}`,calls:r=>`${r.instrumento} · ${r.codigo} — ${r.nombre}`, 'calls-draft':r=>`${r.instrumento} · ${r.codigo} — ${r.nombre}`,versions:r=>`${r.instrumento} · ${r.convocatoria_codigo} · ${r.codigo_version} (${r.estado})`,'versions-draft':r=>`${r.instrumento} · ${r.convocatoria_codigo} · ${r.codigo_version}`,categories:r=>`${r.codigo} — ${r.nombre}`,criteria:r=>`${r.codigo} — ${r.nombre}`,subcriteria:r=>`${r.codigo} — ${r.nombre}`,types:r=>r.nombre_tipo,sources:r=>`${r.nombre_documento} (${r.validacion_estado})`};
function setSelect(el,key){const collection={calls:"convocatorias","calls-draft":"convocatorias",versions:"versiones","versions-draft":"versiones","periodos-filter":"periodos"}[key]||key;let rows=acaData[collection]||[];if(key==='calls-draft')rows=rows.filter(x=>['BORRADOR','ACTIVA'].includes(x.estado));if(key==='versions-draft')rows=rows.filter(x=>x.estado==='BORRADOR');const current=el.value;el.innerHTML='<option value="">Selecciona…</option>'+rows.map(r=>`<option value="${esc(r['id_'+({instrumentos:'instrumento',periodos:'periodo','periodos-filter':'periodo',calls:'convocatoria','calls-draft':'convocatoria',versions:'version','versions-draft':'version',categories:'categoria',criteria:'criterio',subcriteria:'subcriterio',types:'tipo_evidencia',sources:'fuente'}[key])])}">${esc((labelMap[key]||(()=>''))(r))}</option>`).join('');if(el.multiple){el.options[0].disabled=true;}if((current||!el.multiple)&&[...el.options].some(o=>o.value===current))el.value=current;}
function refreshCriteriaScope(){const instrument=document.getElementById('criteriaInstrument')?.value||'',call=document.getElementById('criteriaCall')?.value||'',eligible=(acaData.convocatorias||[]).filter(x=>['BORRADOR','ACTIVA'].includes(x.estado)&&(!instrument||String(x.id_instrumento)===instrument));const hint=document.getElementById('acaVersionHint');if(hint)hint.textContent=eligible.length?'Las convocatorias en borrador también se pueden configurar. Para activar una convocatoria se requiere una versión publicada y validada.':'No hay convocatorias configurables para este instrumento. Crea una convocatoria en estado Borrador desde Convocatorias.';document.querySelectorAll('[data-options="versions-draft"]').forEach(el=>{const current=el.value,rows=(acaData.versiones||[]).filter(v=>v.estado==='BORRADOR'&&(!call||String(v.id_convocatoria)===call));el.innerHTML='<option value="">Selecciona...</option>'+rows.map(v=>`<option value="${esc(v.id_version)}">${esc(labelMap['versions-draft'](v))}</option>`).join('');if(rows.some(v=>String(v.id_version)===current))el.value=current;});renderLists();}
function populate(){document.querySelectorAll('[data-options]').forEach(setSelectByAttr);function setSelectByAttr(el){setSelect(el,el.dataset.options)}
 const criteriaInstrument=document.getElementById('criteriaInstrument'),criteriaCall=document.getElementById('criteriaCall');if(criteriaInstrument&&criteriaCall){const filterCalls=()=>{const instrument=criteriaInstrument.value,current=criteriaCall.value,rows=(acaData.convocatorias||[]).filter(x=>['BORRADOR','ACTIVA'].includes(x.estado)&&(!instrument||String(x.id_instrumento)===instrument));criteriaCall.innerHTML='<option value="">Selecciona...</option>'+rows.map(x=>`<option value="${esc(x.id_convocatoria)}">${esc(labelMap['calls-draft'](x))}</option>`).join('');if(rows.some(x=>String(x.id_convocatoria)===current))criteriaCall.value=current;refreshCriteriaScope();};criteriaInstrument.onchange=filterCalls;criteriaCall.onchange=refreshCriteriaScope;filterCalls();}
 const callForm=document.querySelector('[name="id_instrumento"][data-change="period-filter"]');if(callForm){const period=callForm.form.elements.id_periodo;const fill=()=>{const all=acaData.periodos||[];period.innerHTML='<option value="">Selecciona…</option>'+all.filter(p=>!callForm.value||String(p.id_instrumento)===callForm.value).map(p=>`<option value="${p.id_periodo}">${esc(labelMap['periodos-filter'](p))}</option>`).join('')};callForm.onchange=fill;fill();}
 document.querySelectorAll('[data-change="version"]').forEach(el=>{const drafts=[...(el.options||[])].slice(1);if(!el.value&&drafts.length===1)el.value=drafts[0].value;el.onchange=()=>refreshVersionDependents(el);refreshVersionDependents(el);});
 const fInstrument=document.getElementById('filterInstrument');if(fInstrument){fInstrument.innerHTML='<option value="">Todos</option>'+ (acaData.instrumentos||[]).map(x=>`<option value="${x.id_instrumento}">${esc(x.abreviatura)}</option>`).join('');fInstrument.addEventListener('change',renderLists);}
 const fPeriod=document.getElementById('filterPeriod');if(fPeriod){fPeriod.innerHTML='<option value="">Todos</option>'+ (acaData.periodos||[]).map(x=>`<option value="${x.id_periodo}">${esc(x.instrumento)} ${esc(x.codigo)}</option>`).join('');fPeriod.addEventListener('change',renderLists);}const fState=document.getElementById('filterState');if(fState)fState.addEventListener('change',renderLists);
}
function refreshVersionDependents(versionSelect){const form=versionSelect.form,id=versionSelect.value;const config=[['categories','categoria','Selecciona una categoria','Esta version no tiene categorias. Crea una categoria para continuar.'],['criteria','criterio','Selecciona un criterio','Esta version no tiene criterios configurados.'],['subcriteria','subcriterio','Selecciona un subcriterio','Esta version no tiene subcriterios configurados.'],['sources','fuente','Selecciona una fuente normativa','Esta version no tiene fuentes normativas registradas.']];for(const [key,field,placeholder,empty] of config){const select=form.querySelector(`[data-options="${key}"]`);if(!select)continue;const all=acaData[key]||[],rows=all.filter(row=>String(row.id_version)===id),current=select.value;const first=!id?'Selecciona primero una version borrador':(rows.length?placeholder:empty);select.innerHTML=`<option value="">${esc(first)}</option>`+rows.map(row=>`<option value="${esc(row['id_'+field])}">${esc(labelMap[key](row))}</option>`).join('');if(select.multiple)select.options[0].disabled=true;if(rows.some(row=>String(row['id_'+field])===current))select.value=current;}}
function table(rows,cols,kind){if(!rows.length){const empty={periodo:'Todavía no hay periodos académicos registrados. Crea uno para organizar convocatorias.',convocatoria:'No hay convocatorias para mostrar. Crea una o revisa los filtros aplicados.',version:'Esta convocatoria todavía no tiene versiones. Crea una versión en borrador para comenzar.',categoria:'No hay categorías en esta versión. Agrega una categoría y después registra sus criterios.',criterio:'No hay criterios configurados. Agrega uno dentro de una categoría.',subcriterio:'Esta versión todavía no tiene subcriterios; agrégalos cuando sean necesarios.',requisito:'No hay requisitos documentales configurados para esta versión.',fuente:'No hay fuentes normativas registradas para esta versión.'};return '<p class="academic-help">'+(empty[kind]||'No hay registros para mostrar en esta sección.')+'</p>';}return `<table><thead><tr>${cols.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c[0]])}</td>`).join('')}<td class="actions"><button class="btn" type="button" data-edit="${kind}" data-id="${r['id_'+kind]}">Editar</button>${kind==='periodo'?`<button class="btn" type="button" data-delete-period="${r.id_periodo}">Eliminar</button>`:kind==='convocatoria'?`<button class="btn" type="button" data-detail-call="${r.id_convocatoria}">Detalle</button>${callActions(r)}`:kind==='version'?`<button class="btn" type="button" data-publish="${r.id_version}" ${r.estado!=='BORRADOR'?'disabled':''}>Publicar</button>`:''}</td></tr>`).join('')}</tbody></table>`;}
function callActions(r){if(r.estado==='BORRADOR')return `<button class="btn" type="button" data-state="${r.id_convocatoria}" data-next="ACTIVA">Activar</button><button class="btn" type="button" data-state="${r.id_convocatoria}" data-next="INACTIVA">Inactivar</button>`;if(r.estado==='ACTIVA')return `<button class="btn" type="button" data-state="${r.id_convocatoria}" data-next="CERRADA">Cerrar</button><button class="btn" type="button" data-state="${r.id_convocatoria}" data-next="INACTIVA">Inactivar</button>`;return '';}
function renderLists(){
  if(acaPage==='periodos')document.getElementById('acaPeriods').innerHTML=table(acaData.periodos||[],[['id_periodo','ID'],['instrumento','Instrumento'],['codigo','Codigo'],['nombre','Nombre'],['fecha_inicio','Desde'],['fecha_fin','Hasta'],['estado','Estado']],'periodo');
  if(acaPage==='convocatorias'){
    let rows=acaData.convocatorias||[];const i=document.getElementById('filterInstrument')?.value,p=document.getElementById('filterPeriod')?.value,state=document.getElementById('filterState')?.value;
    if(i)rows=rows.filter(x=>String(x.id_instrumento)===i);if(p)rows=rows.filter(x=>String(x.id_periodo)===p);if(state)rows=rows.filter(x=>x.estado===state);
    document.getElementById('acaCalls').innerHTML=table(rows,[['id_convocatoria','ID'],['instrumento','Instrumento'],['periodo_codigo','Periodo'],['codigo','Codigo'],['nombre','Nombre'],['estado','Estado'],['fecha_apertura','Apertura'],['fecha_cierre','Cierre']],'convocatoria');
  }
  if(acaPage==='criterios'){
    const call=document.getElementById('criteriaCall')?.value||'';let versions=acaData.versiones||[];if(call)versions=versions.filter(x=>String(x.id_convocatoria)===call);document.getElementById('acaVersions').innerHTML=versions.length?table(versions,[['codigo_version','Version'],['convocatoria_codigo','Convocatoria'],['estado','Estado'],['vigencia_desde','Desde'],['vigencia_hasta','Hasta']],'version'):(call?'<p class="academic-help">Esta convocatoria todavía no tiene versiones de criterios. Crea una versión para comenzar su configuración.</p>':'<p class="academic-help">Selecciona una convocatoria para consultar sus versiones.</p>');
    const versionIds=new Set(versions.map(v=>String(v.id_version)));document.getElementById('acaStructure').innerHTML=['categorias','criterios','subcriterios','requisitos'].map(k=>{const rows=(acaData[k]||[]).filter(x=>!call||versionIds.has(String(x.id_version)));return `<h3>${({categorias:'Categorias',criterios:'Criterios',subcriterios:'Subcriterios',requisitos:'Requisitos'})[k]}</h3>${table(rows,Object.keys(rows[0]||{}).slice(0,5).map(x=>[x,x]),k.slice(0,-1))}`}).join('');
  }
  if(acaPage==='fuentes')document.getElementById('acaSources').innerHTML=table(acaData.fuentes||[],[['id_fuente','ID'],['codigo_version','Version'],['nombre_documento','Documento'],['validacion_estado','Validacion'],['responsable','Responsable'],['referencia_url','Referencia']],'fuente');
}async function refresh(){try{const res=await fetch(acaApi,{credentials:'same-origin'}),body=await res.json();if(!res.ok||body.status!=='ok')throw Error(body.message||'No se pudo cargar el catálogo.');const {categorias,criterios,subcriterios,tipos_documentales,fuentes}=body.data;acaData={...body.data,categories:categorias,criteria:criterios,subcriteria:subcriterios,types:tipos_documentales,sources:fuentes};populate();renderLists();acaStatus.textContent='Configuración cargada.';acaStatus.classList.remove('error');}catch(e){acaStatus.textContent=e.message;acaStatus.classList.add('error');}}
async function post(data){const body=new URLSearchParams(data);const r=await fetch(acaSave,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-CSRF-Token':acaCsrf},body});const j=await r.json();if(!r.ok||j.status!=='ok')throw Error(j.message||'No se guardó el cambio.');return j;}
document.querySelectorAll('[data-aca-form]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();try{const result=await post(new FormData(form));if(window.Swal)await Swal.fire({icon:'success',title:'Guardado',text:result.message});const selectedCall=form.elements.id_convocatoria?.value,selectedInstrument=document.getElementById('criteriaInstrument')?.value;form.reset();form.querySelectorAll('input[type=hidden][name^="id_"]').forEach(x=>x.value='');if(acaPage==='criterios'&&selectedCall){form.elements.id_convocatoria.value=selectedCall;document.getElementById('criteriaInstrument').value=selectedInstrument;}await refresh();}catch(err){if(window.Swal)Swal.fire({icon:'error',title:'No se pudo guardar',text:err.message});else alert(err.message);}}));
document.addEventListener('click',async e=>{
 const detail=e.target.closest('[data-detail-call]'),deletePeriod=e.target.closest('[data-delete-period]'),publish=e.target.closest('[data-publish]'),state=e.target.closest('[data-state]'),edit=e.target.closest('[data-edit]');
 try{
  if(deletePeriod){const id=deletePeriod.dataset.deletePeriod,answer=window.Swal?await Swal.fire({icon:'warning',title:'Eliminar periodo',text:'Solo se eliminará si no tiene convocatorias asociadas.',showCancelButton:true,confirmButtonText:'Eliminar',cancelButtonText:'Cancelar'}):{isConfirmed:confirm('Eliminar el periodo si no tiene convocatorias asociadas?')};if(answer.isConfirmed){await post({accion:'periodo_eliminar',id_periodo:id});await refresh();}}
  else if(detail){const row=(acaData.convocatorias||[]).find(x=>String(x.id_convocatoria)===detail.dataset.detailCall);if(row&&window.Swal)await Swal.fire({title:row.nombre,text:[`Instrumento: ${row.instrumento}`,`Periodo: ${row.periodo_codigo}`,`Codigo: ${row.codigo}`,`Estado: ${row.estado}`,`Descripcion: ${row.descripcion||'-'}`,`Apertura: ${row.fecha_apertura||'-'}`,`Cierre: ${row.fecha_cierre||'-'}`].join('\n')});}
  else if(publish){await post({accion:'version_publicar',id_version:publish.dataset.publish});await refresh();}
  else if(state){await post({accion:'convocatoria_estado',id_convocatoria:state.dataset.state,estado:state.dataset.next});await refresh();}
  else if(edit){const kind=edit.dataset.edit,map={periodo:['periodos','periodo'],convocatoria:['convocatorias','convocatoria'],version:['versiones','version'],categoria:['categorias','categoria'],criterio:['criterios','criterio'],subcriterio:['subcriterios','subcriterio'],requisito:['requisitos','requisito'],fuente:['fuentes','fuente']};const [collection,singular]=map[kind]||[];const row=(acaData[collection]||[]).find(x=>String(x['id_'+singular])===edit.dataset.id);if(!row)return;const form=document.querySelector(`[data-aca-form] input[name="id_${singular}"]`)?.form;if(!form)return;for(const [key,value] of Object.entries(row)){const el=form.elements[key];if(!el)continue;if(el.type==='checkbox')el.checked=Boolean(Number(value));else el.value=value??'';}form.scrollIntoView({behavior:'smooth',block:'center'});}
 }catch(err){if(window.Swal)Swal.fire({icon:'error',title:'Accion no completada',text:err.message});else alert(err.message);}
});
refresh();
</script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
